custom_css:
.sc-tw :root{
            --moss: oklch(92% 0.03 150);
            --emerald: oklch(34% 0.08 160);
            --forest: oklch(22% 0.05 160);
            --fog: rgba(255, 255, 255, .14);
            --text: oklch(20% 0.02 160);
            --light: rgba(255, 255, 255, .58);
        }.sc-tw *{
            box-sizing: border-box;
        }.sc-tw html{
            scroll-behavior: smooth;
        }.sc-tw{
            margin: 0;
            overflow-x: hidden;
            font-family: 'Manrope', sans-serif;
            background:
                radial-gradient(circle at top left, rgba(198, 255, 221, .55), transparent 25%),
                radial-gradient(circle at bottom right, rgba(142, 202, 174, .18), transparent 20%),
                linear-gradient(180deg, #eef7ef 0%, #dbeadf 100%);
            color: var(--text);
        }.sc-tw body::before{
            content: '';
            position: fixed;
            inset: 0;
            pointer-events: none;
            background:
                radial-gradient(circle at 20% 10%, rgba(255, 255, 255, .55), transparent 15%),
                radial-gradient(circle at 80% 20%, rgba(255, 255, 255, .4), transparent 14%),
                radial-gradient(circle at 40% 80%, rgba(255, 255, 255, .3), transparent 18%);
            mix-blend-mode: screen;
            opacity: .8;
            z-index: -1;
        }.sc-tw .serif{
            font-family: 'Instrument Serif', serif;
            letter-spacing: -.05em;
        }.sc-tw .mist-button{
            position: relative;
            overflow: hidden;
            border-radius: 999px;
            background: rgba(255, 255, 255, .18);
            backdrop-filter: blur(30px) saturate(1.1);
            border: none;
            color: white;
            transition: .7s cubic-bezier(.16, 1, .3, 1);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .28),
                0 12px 50px rgba(10, 50, 25, .16);
        }.sc-tw .mist-button::before{
            content: '';
            position: absolute;
            inset: 0;
            background: radial-gradient(circle at center, rgba(255, 255, 255, .22), transparent 70%);
            opacity: 0;
            transition: .7s ease;
        }.sc-tw .mist-button:hover{
            transform: translateY(-4px) scale(1.02);
            background: rgba(255, 255, 255, .24);
        }.sc-tw .mist-button:hover::before{
            opacity: 1;
            transform: scale(1.3);
        }.sc-tw .hero-video{
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            animation: zoom 18s ease-in-out infinite alternate;
        }.sc-tw .hero-overlay{
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at top, rgba(255, 255, 255, .16), transparent 30%),
                linear-gradient(180deg, rgba(0, 0, 0, .1), rgba(0, 0, 0, .45));
        }.sc-tw .condense{
            opacity: 0;
            filter: blur(22px);
            transform: translateY(40px) scale(.96);
            animation: condense 1.4s cubic-bezier(.16, 1, .3, 1) forwards;
        }.sc-tw .condense:nth-child(2){
            animation-delay: .18s;
        }.sc-tw .condense:nth-child(3){
            animation-delay: .32s;
        }.sc-tw .header-float{
            background: rgba(0, 0, 0, 0.3);
            backdrop-filter: blur(28px) saturate(1.5);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, 0.08),
                0 14px 60px rgba(0, 0, 0, 0.4);

            border: 1px border rgba(255, 255, 255, 0.05);
        }.sc-tw .vapor{
            background: rgba(255, 255, 255, .12);
            backdrop-filter: blur(32px);
            box-shadow:
                0 30px 80px rgba(11, 40, 20, .1);
        }.sc-tw .ascend-light{
            background:
                radial-gradient(circle at top left, rgba(255, 255, 255, .55), transparent 20%),
                linear-gradient(180deg, #edf7ef 0%, #d7eadb 100%);
        }.sc-tw .ascend-mid{
            background:
                radial-gradient(circle at top, rgba(255, 255, 255, 0.458), transparent 40%),
                linear-gradient(180deg, #1a2e22 0%, #1b5b2c 100%);

            position: relative;
        }.sc-tw .ascend-deep{
            background:
                radial-gradient(circle at top, rgba(255, 255, 255, .06), transparent 14%),
                linear-gradient(180deg, #234334 0%, #11251c 100%);
        }.sc-tw .organic{
            border-radius: 42% 58% 61% 39% / 38% 36% 64% 62%;
        }.sc-tw .leaf{
            border-radius: 58% 42% 64% 36% / 41% 60% 40% 59%;
        }.sc-tw .canopy{
            position: absolute;
            backdrop-filter: blur(30px);
            background: rgba(255, 255, 255, .14);
            box-shadow:
                0 30px 80px rgba(16, 50, 30, .14);
            animation: float 10s ease-in-out infinite;
        }.sc-tw .earth{
            position: relative;
            overflow: hidden;
        }.sc-tw .earth::before{
            content: '';
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 30% 20%, rgba(104, 160, 123, .18), transparent 20%),
                radial-gradient(circle at 70% 80%, rgba(255, 255, 255, .04), transparent 18%);
            opacity: .7;
        }.sc-tw .moss-grid{
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255, 255, 255, .03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255, 255, 255, .03) 1px, transparent 1px);
            background-size: 70px 70px;
            mask-image: radial-gradient(circle at center, black 40%, transparent 90%);
        }

        @keyframes condense {to{
                opacity: 1;
                filter: blur(0);
                transform: translateY(0) scale(1);
            }
        }

        @keyframes float {0%,100%{
                transform: translateY(0px);
            }50%{
                transform: translateY(-20px);
            }
        }

        @keyframes zoom {from{
                transform: scale(1.02);
            }to{
                transform: scale(1.12);
            }
        }.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
            animation-duration: .8s;
            animation-timing-function: cubic-bezier(.16, 1, .3, 1);
